/* Token Radar's theme: a dark desk. One palette, two radii, two families; everything else is
   spacing, a hairline and a type step. No external assets, no network. */
:root {
  --canvas: #0b0e13;
  --surface: #12161f;
  --surface-2: #171d29;
  --ink: #e8ecf1;
  --muted: #93a0b4;
  --faint: #5d6b80;
  --border: #232c3d;
  --accent: #f5b83d;
  --accent-ink: #1a1405;
  --cyan: #57c8d8;
  --green: #4cc38a;
  --red: #f26d6d;
  --radius-control: 8px;
  --radius-panel: 12px;
  --font-body: system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-num: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --step-1: 4px;
  --step-2: 8px;
  --step-3: 12px;
  --step-4: 16px;
  --step-5: 24px;
  --step-6: 32px;
}
* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font: 400 15px/1.55 var(--font-body);
}
h1, h2, h3 { margin: 0; letter-spacing: -0.02em; }
h1 { font-size: 28px; line-height: 1.15; font-weight: 700; }
h2 { font-size: 19px; line-height: 1.25; font-weight: 650; }
h3 { font-size: 15px; line-height: 1.3; font-weight: 650; }
p { margin: 0; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
a { color: var(--cyan); }
.skip { position: absolute; left: -999px; top: 0; background: var(--accent); color: var(--accent-ink); padding: var(--step-2) var(--step-3); border-radius: 0 0 var(--radius-control) 0; }
.skip:focus { left: 0; }
.loading { color: var(--muted); padding: var(--step-6); text-align: center; }
.wrap { max-width: 1180px; margin: 0 auto; padding: 0 var(--step-4) var(--step-6); }
header.hero { padding: var(--step-5) 0 var(--step-4); border-bottom: 1px solid var(--border); }
header.hero .kicker { color: var(--accent); font: 600 12px/1.4 var(--font-num); letter-spacing: 0.14em; text-transform: uppercase; }
header.hero h1 { margin-top: var(--step-2); }
header.hero .lede { color: var(--muted); max-width: 72ch; margin-top: var(--step-2); }
.stats { display: flex; flex-wrap: wrap; gap: var(--step-3); margin-top: var(--step-4); }
.stat { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-panel); padding: var(--step-3) var(--step-4); min-width: 150px; }
.stat b { display: block; font: 700 22px/1.2 var(--font-num); color: var(--ink); }
.stat span { color: var(--muted); font-size: 12.5px; }
.stat b.accent { color: var(--accent); }
.tabs { display: flex; gap: var(--step-2); margin: var(--step-4) 0; flex-wrap: wrap; }
.tab { background: var(--surface); border: 1px solid var(--border); color: var(--muted); border-radius: 999px; padding: 7px 16px; font-weight: 600; }
.tab[aria-selected="true"] { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
.controls { display: flex; flex-wrap: wrap; gap: var(--step-2); align-items: center; margin-bottom: var(--step-3); }
.controls input[type="search"], .controls select {
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-control);
  padding: 8px 12px; color: var(--ink);
}
.controls input[type="search"] { min-width: 220px; flex: 1 1 220px; }
.controls label.chk { display: inline-flex; gap: 6px; align-items: center; color: var(--muted); font-size: 14px; }
.count { color: var(--muted); font-size: 13.5px; margin-left: auto; }
table.board { width: 100%; border-collapse: collapse; background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-panel); overflow: hidden; }
table.board th, table.board td { padding: 9px 12px; text-align: left; border-bottom: 1px solid var(--border); vertical-align: middle; }
table.board thead th { color: var(--muted); font-size: 12px; letter-spacing: 0.06em; text-transform: uppercase; background: var(--surface-2); white-space: nowrap; }
table.board thead th button { background: none; border: 0; color: inherit; font: inherit; padding: 0; text-transform: inherit; letter-spacing: inherit; }
table.board thead th button:hover { color: var(--ink); }
table.board tbody tr { cursor: pointer; }
table.board tbody tr:hover { background: var(--surface-2); }
table.board tbody tr.selected { background: #241d08; }
.num { font-family: var(--font-num); font-variant-numeric: tabular-nums; text-align: right; white-space: nowrap; }
td.num, th.num { text-align: right; }
.rank { font: 700 15px var(--font-num); color: var(--accent); }
.name b { display: block; font-weight: 650; }
.name span { color: var(--faint); font-size: 12.5px; font-family: var(--font-num); }
.badge { display: inline-block; font-size: 11.5px; font-weight: 650; padding: 2px 8px; border-radius: 999px; background: #1d2b1f; color: var(--green); border: 1px solid #2a4a33; }
.badge.watch { background: #2a2103; color: var(--accent); border-color: #574a12; }
.pos { color: var(--green); }
.neg { color: var(--red); }
.cat { color: var(--muted); font-size: 13.5px; }
.detail { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-panel); padding: var(--step-4) var(--step-5); margin-top: var(--step-4); }
.detail h2 { font-size: 22px; }
.detail .sub { color: var(--muted); margin-top: var(--step-1); }
.modelgrid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: var(--step-2); margin: var(--step-4) 0; }
.mcell { background: var(--surface-2); border: 1px solid var(--border); border-radius: var(--radius-control); padding: var(--step-3); }
.mcell b { display: block; font: 700 16px/1.3 var(--font-num); }
.mcell span { color: var(--muted); font-size: 12px; }
.mcell code { font-family: var(--font-num); font-size: 12px; color: var(--cyan); }
.farm { margin: var(--step-3) 0 0; padding-left: 20px; }
.farm li { margin-bottom: var(--step-2); }
.farm li::marker { color: var(--accent); font-weight: 700; }
.comps { width: 100%; border-collapse: collapse; margin-top: var(--step-2); }
.comps th, .comps td { padding: 6px 10px; text-align: left; border-bottom: 1px solid var(--border); font-size: 13.5px; }
.comps th { color: var(--muted); font-size: 11.5px; text-transform: uppercase; letter-spacing: 0.05em; }
.method { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-panel); padding: var(--step-4) var(--step-5); margin-top: var(--step-4); }
.method h2 { margin-bottom: var(--step-2); }
.method p { color: var(--muted); margin-bottom: var(--step-3); max-width: 78ch; }
.method p b, .method li b { color: var(--ink); }
.method code { font-family: var(--font-num); font-size: 13px; color: var(--cyan); background: var(--surface-2); padding: 1px 5px; border-radius: 4px; }
.method ul { margin: 0 0 var(--step-3); padding-left: 20px; color: var(--muted); }
.method li { margin-bottom: 6px; }
.warn { border: 1px solid #574a12; background: #211b05; border-radius: var(--radius-panel); padding: var(--step-3) var(--step-4); color: #e8d9a0; margin-top: var(--step-4); font-size: 14px; }
footer.foot { color: var(--faint); font-size: 12.5px; margin-top: var(--step-5); border-top: 1px solid var(--border); padding-top: var(--step-3); }
.empty { color: var(--muted); padding: var(--step-5); text-align: center; }
@media (max-width: 720px) {
  .controls input[type="search"] { flex-basis: 100%; }
  table.board th:nth-child(4), table.board td:nth-child(4) { display: none; }
}
